{
  "items": [
    {
      "name": "Polynomial.mod_eq_of_dvd_sub",
      "module_name": "Mathlib.Algebra.Polynomial.FieldDivision",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Field R] {p₁ p₂ q : Polynomial R}, q ∣ p₁ - p₂ → p₁ % q = p₂ % q"
    },
    {
      "name": "Polynomial.aeval_iterate_derivative_of_lt",
      "module_name": "Mathlib.Algebra.Polynomial.SumIteratedDerivative",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] {A : Type u_3} [inst_1 : CommRing A] [inst_2 : Algebra R A] (p : Polynomial R)\n  (q : ℕ) (r : A) {p' : Polynomial A},\n  Polynomial.map (algebraMap R A) p = (Polynomial.X - Polynomial.C r) ^ q * p' →\n    ∀ {k : ℕ}, k < q → (Polynomial.aeval r) ((⇑Polynomial.derivative)^[k] p) = 0"
    },
    {
      "name": "Polynomial.modByMonic_eq_of_dvd_sub",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {p₁ p₂ q : Polynomial R}, q.Monic → q ∣ p₁ - p₂ → p₁ %ₘ q = p₂ %ₘ q"
    },
    {
      "name": "Polynomial.isRoot_of_isRoot_of_dvd_derivative_mul",
      "module_name": "Mathlib.Algebra.Polynomial.FieldDivision",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [NoZeroDivisors R] [CharZero R] {f g : Polynomial R},\n  f ≠ 0 → f ∣ Polynomial.derivative f * g → ∀ {a : R}, f.IsRoot a → g.IsRoot a"
    },
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.X_sub_C_dvd_derivative_of_X_sub_C_dvd_divByMonic",
      "module_name": "Mathlib.Algebra.Polynomial.FieldDivision",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Field K] (f : Polynomial K) {a : K},\n  Polynomial.X - Polynomial.C a ∣ f /ₘ (Polynomial.X - Polynomial.C a) →\n    Polynomial.X - Polynomial.C a ∣ Polynomial.derivative f"
    }
  ]
}
